INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bb5c0031-3332-4aee-bc88-b226aa4fca49', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Filesystem Inspector', 'After mounting, create /mnt/data/test.txt with "hello". Run: lsblk -f | head -3. What filesystem type is shown for your loop device?', 100, '$2b$10$hHLKLRhIQw6rsAwR3jwn.Ol/BQa7TURoOV995ih5dBGIosOepc2sa'ON CONFLICT DO NOTHING)
