INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('27beda7c-d00e-494a-be7b-429c035237ea', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'VG Builder', 'Create volume group: vgcreate myvg /tmp/disk1.img /tmp/disk2.img. Run: vgdisplay myvg | grep "PE Size". What is the PE size?', 100, '$2b$10$DSe2R7MZVccaPqxyUU9yguAzz.KTsoLw9Rqr3HUXlMyZhtzPzZG7O'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d898fb70-deb4-4209-88cd-ade116954fd6', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'LV Crafter', 'Create logical volume: lvcreate -L 30M -n mylv myvg. Run: lvdisplay /dev/myvg/mylv | grep "LV Size". What is the size?', 100, '$2b$10$iJIjGio6SyN44CT2doScRuMDhTHOtYR78HwfrfQBKdqvQIJMZi7Vm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7654a63c-c93e-42ad-b394-ebe7a11e4cc2', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'RAID Builder', 'Create RAID0: mdadm --create /dev/md0 --level=0 --raid-devices=2 /tmp/disk1.img /tmp/disk2.img 2>/dev/null; Run: cat /proc/mdstat | grep md0 | awk "{print $4}". What is the status?', 100, '$2b$10$SYa5WD/TLoBy6BNWD4tOfezD/ycmlC7T2c07u3O67PPtAU4JVBACa'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('22014ade-e29a-4f91-9bca-155e6375f1c3', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Swap Creator', 'Create 50MB swap: dd if=/dev/zero of=/tmp/swap.img bs=1M count=50 && mkswap /tmp/swap.img && swapon /tmp/swap.img. Run: swapon --show | wc -l. How many swap devices (minus header)?', 100, '$2b$10$SZbW6dqajKWx7DDYiXT1WeIORV6oIyLhl7fmQ7Sev2Id.wN3cPc5O'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4ea8c3ea-6ba5-4f56-bbd1-289126966522', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'DF Detective', 'Run: df -h --output=source,size,used,avail,target | grep tmp | head -1. What is the mount point?', 75, '$2b$10$sNU2tlaAR8Ocfz967H6omOy9DI5o9o4KTBy4U50vorq87qXSqVHEW'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d1e4ef1c-1507-4b17-a403-d8aa40470766', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fstab Editor', 'Add to /etc/fstab: /tmp/disk.img /mnt/data ext4 loop 0 0. Run: grep "/mnt/data" /etc/fstab | awk "{print $3}". What filesystem type is listed?', 100, '$2b$10$xrdCNiUrVN.ZM4UyYFifL.i66BMx3khNvPz3uh.2hTKr6Lkl58Hcy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dba42022-2127-43dc-b782-45d965f0d231', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Inode Counter', 'Run: df -i / | tail -1 | awk "{print $4}". How many free inodes?', 100, '$2b$10$Nl283Kftvp7pB5tX/nXvIOva2lZFsobVJ/0.POqgUFmaQFzH7Xk2S'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0594b33e-75a5-460c-85af-3529f2c82ef7', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Du Analyzer', 'Create files in /mnt/data (dd if=/dev/zero of=/mnt/data/bigfile bs=1M count=10). Run: du -sh /mnt/data | awk "{print $1}". What is the size?', 100, '$2b$10$ayiQvfOQ63y9a2a.2LcreuYkUO.Z1yAHbvb07JVof7vM9i7ct6pYG'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6cda017d-1f6e-4988-b636-eeee42af30eb', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'UUID Finder', 'Run: blkid /dev/loop0 2>/dev/null | grep -o "UUID=\"[^ ]*\"" | head -1. What is the UUID format? (just answer "uuid" if you can see it)', 75, '$2b$10$xn5vhvzoNX3etSszfPZ4dutQUcEBRtbB2aTGZSkS6gugADJCLfmy2'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5c8d7a33-db2d-4c85-823c-ce8f9a5276fc', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fdisk Explorer', 'Run: fdisk -l /tmp/disk.img 2>/dev/null | head -5. What disk identifier type is shown?', 100, '$2b$10$d.lsNPzOkfotFt6i47DvRetChuX5ODdrk8Bg6JeD9l48MrGCJgCIS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3c6aa194-4775-4540-9197-feb8747f7356', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Cleanup Crew', 'Run: umount /mnt/data && losetup -D && vgremove -f myvg 2>/dev/null; echo "storage_done". What is the output?', 75, '$2b$10$OaE1nF0cNgnff89vAtuIseWUDyVNA471y454mqsSPzMGRkWooEEq.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('14ad77f4-0e38-45b8-ad90-ee71b837269f', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Tar Crafter', 'Create /home/student/backup_data/ with 3 files (a.txt, b.txt, c.txt). Pack: tar czf /tmp/backup.tar.gz -C /home/student backup_data. Run: tar tzf /tmp/backup.tar.gz | wc -l. How many entries?', 75, '$2b$10$oCFcjcfrPCZi0vJbcv1Wq.Chh1VhV62F5ZoK/h8pPZ4j9sCWOqxbe'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('12ef7b19-2615-4dba-a5a0-653f827f7dc7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Scheduler', 'Add cron job: echo "0 * * * * echo backup_ok > /tmp/cron_proof" | crontab -. Run: crontab -l | wc -l. How many cron entries?', 75, '$2b$10$PpUhzyFcliMDnQjrjACDd.NZcYCcL.ijk/Ak3UFq8K61mtAgZBn2O'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4fc30add-cd3a-464e-80c2-c1168ea23b16', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Restore Tester', 'Create /tmp/restore_dir/. Extract backup: tar xzf /tmp/backup.tar.gz -C /tmp/restore_dir. Run: ls /tmp/restore_dir/backup_data/ | wc -l. How many files restored?', 100, '$2b$10$dA4YQRYgO87IhRqsWkZ5r.P8DubHDggg0yGzTDk/Oki5g.qvZ6Kny'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('630aa2a9-d43f-4784-8bb0-7c74ca262113', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Incremental Creator', 'Create new file d.txt. Create incremental: tar czf /tmp/incr.tar.gz -C /home/student/backup_data --newer=a.txt . Run: tar tzf /tmp/incr.tar.gz. What file is listed?', 100, '$2b$10$JLky9qv8hZ1/K52G3V64bu.YFPyHPy13TCESjEVUG0amVOKtQ1ee6'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('54ec38ef-e89e-4b2c-98c1-9fbf23601304', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'rsync Master', 'Create /tmp/src_dir/ and /tmp/dst_dir/. Create file in src. Run: rsync -av /tmp/src_dir/ /tmp/dst_dir/ && ls /tmp/dst_dir/. What file is synced?', 100, '$2b$10$cSA0AShl0g1ZFdWynDicHuX2rnEHH7YbXvfNBJ48xzVJJZ/.1wfA2'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fedb7cb6-3286-48e0-bfe0-4c7e2a16e8b7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Exclusion Expert', 'Create files: log.txt, data.csv, log2.txt. Run: tar czf /tmp/no_logs.tar.gz --exclude="log*" -C /home/student/backup_data . Run: tar tzf /tmp/no_logs.tar.gz | grep -c log. How many log files included?', 100, '$2b$10$8ZeV7IQGLoBVu0K4dBrRM./kQTqmacL2Er8L0WVrA3RRB9aC8JwhG'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f715d4b6-5ca9-4cfc-a655-f3cde1665663', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Compression Pro', 'Compare: tar czf /tmp/gz.tar.gz -C /home/student/backup_data . vs tar cJf /tmp/xz.tar.xz -C /home/student/backup_data . Run: ls -la /tmp/gz.tar.gz /tmp/xz.tar.xz | awk "{print $5, $9}". Which is smaller?', 100, '$2b$10$nQ0.Sito8dHTRZwfXaPTFe0Szn/GrJt4D7saggfUd2/tsA/llffiy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cb792593-8bff-4634-823a-771f19232b9b', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Verify Expert', 'Run: tar tzf /tmp/backup.tar.gz > /tmp/list.txt && md5sum /tmp/list.txt. What is the first 8 chars of the hash?', 100, '$2b$10$y2F0U6p4/MR8TjANwswCSu1GUIxmoE56ciTNC2nI4f.TDhe/ZOOji'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5bf445a4-b1e7-4e04-bdc7-57c933963d6d', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Docker Backup', 'Run: docker run -d --name db-backup alpine:3.18 sleep 300. Then: docker export db-backup > /tmp/container_backup.tar && wc -c /tmp/container_backup.tar. How many bytes (approximately)?', 100, '$2b$10$hMZeNsOWpNMjf2yX1ZCumeS7DA3UXkqAIVAw62KIL5iwlG3h3ve9q'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b34519b4-5b55-43bf-a5b0-c5e992c719e1', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Checker', 'Run: cat /var/spool/cron/crontabs/root 2>/dev/null | head -1. What is the cron schedule?', 75, '$2b$10$ZU9OEthgFhrkyYAbhpnCC.qolKU8i7ikNBZ6TLCpk7QPgR6eNo13S'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7090755d-d174-4a90-9a71-05878c02597f', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Diff Backup', 'Create /tmp/original/file.txt with "old". Copy to /tmp/backup_version/. Change original to "new". Run: diff /tmp/original/file.txt /tmp/backup_version/file.txt. What is shown?', 100, '$2b$10$s7zHqkGuwTiFMmmz8eWXIevh6vasDUZyPau57IA7gGUfy3wngFZ8G'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('88539e5e-505e-46f7-88b2-72eca3a96101', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Archive Inspector', 'Run: file /tmp/backup.tar.gz. What is the detected type?', 75, '$2b$10$KFHJd1riNgaN/yypDkI52OPFo/eOx8LpsKCtZ4UA7DTveFBN8PtFy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('57d0c742-50ad-4988-aa43-925cdb788b83', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cleanup Script', 'Create /home/student/cleanup.sh that removes /tmp/restore_dir, /tmp/incr.tar.gz, /tmp/gz.tar.gz, /tmp/xz.tar.xz and echoes "cleaned". chmod +x and run. What is the output?', 100, '$2b$10$bJ86u3iZO6wmUK6qB2RgweWK6trA.kb5mIOol7JbOOUYkZJeLEnna'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('893d77f4-024b-4a39-b11b-8867daa4109a', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Checksum Verifier', 'Run: sha256sum /tmp/backup.tar.gz | awk "{print $1}" | wc -c. How many characters is the SHA256 hash?', 75, '$2b$10$bnSo5Q.kZF5ML5f0aP0dMOuDAurloYuQm5NchUHgtoPAfO7lmCQqO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9e84b11f-27ee-4a0e-85bb-5426aff390db', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Date Stamped Backup', 'Run: tar czf /tmp/backup_$(date +%Y%m%d).tar.gz -C /home/student/backup_data . && ls /tmp/backup_*.tar.gz | wc -l. How many date-stamped backups?', 100, '$2b$10$8vYFiTVRshsbtowyagHHPuU.wZ564Hk2Ww0f6xlVDQlsUwfPwTiou'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f7d9fed4-05a5-4b49-8d75-baa224b939a2', '884ee166-21d8-4336-a519-6ccdf111068c', 'iptables List', 'Run: iptables -L -n | head -3. What is the first chain name shown?', 50, '$2b$10$aB8eF4n.YLS33O5xg1ggqOWZxHVNgOxoe/kYtzDEuAjMpvvnyHzti'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e1ccfa8e-965a-43bc-b02d-d89cccef05aa', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Creator', 'Run: iptables -A INPUT -p tcp --dport 8080 -j ACCEPT && iptables -L INPUT -n | grep 8080. What target is shown?', 75, '$2b$10$bPLBsgcgeCTFtmU23Cmz2uxHs99B9JlcD1QR4rU2ohjgPSI9l2n4W'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cbd9cc6f-ca1b-4cea-8021-97521347c321', '884ee166-21d8-4336-a519-6ccdf111068c', 'Port Blocker', 'Run: iptables -A INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep 9999. What target?', 75, '$2b$10$WrIjm4sJLOorra.7orASCOs1FKivyNYhF65pPlPxvGA9w.k4me44K'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e0cc96ff-bc0b-4c51-93c4-ed6b6ae36cb4', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Deleter', 'Run: iptables -D INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep -c 9999. How many rules for port 9999?', 100, '$2b$10$6gxENYFmvKZUYiojuX66.OyoueG4GpMnBXjnDgseNZcQVWKbkrvE.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6e550ea8-88db-4fe5-977b-9f11cabdf1ea', '884ee166-21d8-4336-a519-6ccdf111068c', 'Chain Creator', 'Run: iptables -N MYCHAIN && iptables -L | grep MYCHAIN. What chain name appears?', 100, '$2b$10$3Ix.64KroDhdxiMVlWjWCef8HADNhREipZ/baUYVykmjIHpCS55W6'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e7679983-8efb-412d-87b6-e886de8e54a4', '884ee166-21d8-4336-a519-6ccdf111068c', 'IP Blocker', 'Run: iptables -A INPUT -s 10.10.10.10 -j DROP && iptables -L INPUT -n | grep 10.10.10.10. What target?', 100, '$2b$10$CdEntQ6M.kArEFL5BDMEeOMW/9DVG1mb0W3kVDu8uDddO53CfHSRO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8e9fc54b-363e-4768-b48e-55412c9f2b35', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rate Limiter', 'Run: iptables -A INPUT -p tcp --dport 80 -m limit --limit 10/min --limit-burst 20 -j ACCEPT && iptables -L INPUT -n | grep "limit:10/min". Is limit shown? (yes/no)', 100, '$2b$10$.ZF7zRiTY4jlj4ciCSgVjOG.5I.1iRT.k9Qv1ORam05pAb9F2Gae.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('da594c53-5e79-49e0-a915-2d9ec907ea3b', '884ee166-21d8-4336-a519-6ccdf111068c', 'State Inspector', 'Run: iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT && iptables -L INPUT -n | grep ESTABLISHED. What states are listed?', 100, '$2b$10$e89IO1bknHZAMl9oMwDoFO04RMFtyyrz7cZKtYlo4acnNlKFLWldG'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9a0d75ef-4446-4a94-9b8f-613780c5609e', '884ee166-21d8-4336-a519-6ccdf111068c', 'NAT Creator', 'Run: iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80 && iptables -t nat -L PREROUTING -n | grep 8080. What target?', 100, '$2b$10$dzOjfvbhaVtgEreFT7G5qe8XORUBk10awV13kthJ/jl3BjmxW4QNm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f1ce2229-f23a-4564-8327-00f5b7efc6e5', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Saver', 'Run: iptables-save > /tmp/iptables_rules.txt && wc -l /tmp/iptables_rules.txt. How many lines of rules?', 100, '$2b$10$n3wXw0Ae3MrTENbkiAgv1OQFOXbO5dWm0yEq.By0oQzQYAECSlSfa'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('528dda47-0a90-4129-8dcd-ac02bbb4ce11', '884ee166-21d8-4336-a519-6ccdf111068c', 'Log Logger', 'Run: iptables -A INPUT -p tcp --dport 8080 -j LOG --log-prefix "FIREWALL: " && iptables -L INPUT -n | grep LOG. What log prefix is shown?', 100, '$2b$10$g97UYIcjyF1p0UuXQk3zkeoaWZbDVCOLbL2BMzhUz.7MwDpbS/2BK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('32f6ce82-0eef-4eb5-8173-177f35e961bd', '884ee166-21d8-4336-a519-6ccdf111068c', 'Interface Binder', 'Run: iptables -A INPUT -i eth0 -j ACCEPT && iptables -L INPUT -n | grep eth0. What interface is shown?', 100, '$2b$10$H/yHwfKuWac9pvjqEed3WO4rzdOy0A5Yr62xKJ/36cSmWLSCcYbCu'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c7e93835-3751-4580-8bc0-ec58d956fd98', '884ee166-21d8-4336-a519-6ccdf111068c', 'Packet Counter', 'Run: iptables -Z INPUT && iptables -L INPUT -v -n | head -3. What is the pkts count for INPUT chain?', 100, '$2b$10$OE0KcCvtx1OoHmZJ/p7tx.HbIfcvojHKrRmzsp6/hwjX4jlFOtJMG'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a9bc2e0b-1c84-40b3-b1f4-139a5538aa2f', '884ee166-21d8-4336-a519-6ccdf111068c', 'Flush Master', 'Run: iptables -F MYCHAIN && iptables -L MYCHAIN -n | wc -l. How many rules in MYCHAIN after flush?', 75, '$2b$10$nG.CmLHAfiXgKkuZc9f5iORxb5QymZhf8T.7PDKdzGaVXLSZNwyLu'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c2e21c4e-dd86-4f5c-9a95-9f294abb980f', '884ee166-21d8-4336-a519-6ccdf111068c', 'Cleanup', 'Run: iptables -F && iptables -X MYCHAIN 2>/dev/null; iptables -t nat -F PREROUTING 2>/dev/null; echo "firewall_done". What is the output?', 75, '$2b$10$q86.5ipuUfL3Ph70unm5DebBddJ3p9AbpE3rw.bXuZPE2w1U5h9zK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('14914777-cda7-43ef-ab1b-70e2f4a2c978', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Creator', 'Create zone file: /etc/bind/zones/aeroacademy.local. Add SOA record for aeroacademy.local. Run: named-checkzone aeroacademy.local /etc/bind/zones/aeroacademy.local 2>&1 | tail -1. What is the status?', 75, '$2b$10$Kxwg.4pn7Ou/7hDMijt36eK9rKiNJCH/xPzibAaY2F0pUjKNIp45O'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('032c76bd-ca83-488e-b3cb-280d19288e91', 'e0decd06-4a2e-4f94-965a-79854928514d', 'A Record', 'Add A record: aeroacademy.local IN A 192.168.1.100. Run: grep "IN A" /etc/bind/zones/aeroacademy.local. What IP is shown?', 75, '$2b$10$DTwGrzjKYvBaBi33OnC5DeRNtP0I3RZNGGA/Hws0lnBS7iUXz.90O'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('942a71c1-d06c-45f4-907c-aaf1be831985', 'e0decd06-4a2e-4f94-965a-79854928514d', 'MX Record', 'Add MX record: aeroacademy.local IN MX 10 mail.aeroacademy.local. Run: dig MX aeroacademy.local +short. What is the mail server?', 100, '$2b$10$3huGHQ3ZI69fFzLbOxwDgOiTlcqwK4ZyqFzqopiDVPCcNbzVJXGWy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a8d9e415-98e5-4f8c-b953-d0503bef7b45', 'e0decd06-4a2e-4f94-965a-79854928514d', 'CNAME Record', 'Add CNAME: www.aeroacademy.local IN CNAME aeroacademy.local. Run: dig www.aeroacademy.local +short. What does it resolve to?', 100, '$2b$10$Fm8WlHw3sURMiTJYcWIpauI2S/JtF3eK2It4OFLLzrET9JN81gzgS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7ef048d2-735f-4561-9a62-a7ee333023c3', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Reverse Zone', 'Create reverse zone for 1.168.192.in-addr.arpa. Add PTR: 100 IN PTR aeroacademy.local. Run: named-checkzone 1.168.192.in-addr.arpa /etc/bind/zones/reverse.local 2>&1 | tail -1. What status?', 100, '$2b$10$CKViOZK6TNDhYCoKYUoPC.ErHSptF2yKvMrZh/gVmlazgEsXip95m'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('85d29c72-afa1-4006-8c2c-883cd2808c56', 'e0decd06-4a2e-4f94-965a-79854928514d', 'NS Record', 'Add NS record: aeroacademy.local IN NS ns1.aeroacademy.local. Run: dig NS aeroacademy.local +short. What nameserver is shown?', 100, '$2b$10$SGvLxmcbL0XHt3bnrznJuOtqAY2zGdHg7H71yO0G5FxPGzMC1q.0C'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('68bd9b9e-c85e-46cc-820b-81301694931c', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TXT Record', 'Add TXT record: aeroacademy.local IN TXT "v=spf1 mx -all". Run: dig TXT aeroacademy.local +short. What is the TXT value?', 100, '$2b$10$gQh2Nch9e8RaY9g3USxHiu4jcIisCMpGTRDagvskxnDkH86GmFIN2'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5d744b5a-2e0c-419f-b0e0-245b68c73c97', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Inspector', 'Run: cat /etc/bind/named.conf.local | grep "zone" | wc -l. How many zones are defined?', 75, '$2b$10$HtGKlc0LXEt6ccxv0ssvGema7psIRn.bGjBJFScSjoLd7hr9obKnK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d3f1de2b-47f2-443f-bd0d-24a8d2ba35d9', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Serial Bumper', 'Update SOA serial to 2024010101. Run: grep serial /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the serial number?', 100, '$2b$10$vmfSxD8bD7Evk5Q.MlQ3t.orI2EQ9FNWWY8Q0VpXKcKHTmg4qO0IC'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('49640016-ed77-4602-9c7c-c1e01e98386f', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TTL Set', 'Set TTL to 3600 in the zone file. Run: grep -m1 ";" /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the TTL?', 75, '$2b$10$HJZw4l8p1GP6vgGuiO4arONRX4PQRMT8cvy34Y62qEFrLHY/roZmy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5911a014-9afa-409c-b8ff-bd81985d6629', 'e0decd06-4a2e-4f94-965a-79854928514d', 'AAAA Record', 'Add AAAA record: aeroacademy.local IN AAAA ::1. Run: dig AAAA aeroacademy.local +short. What is the IPv6 address?', 100, '$2b$10$OI1l6tUoMHHfpYidK0lhVOMQbDhNUxP9.DaMrDuKsYukwO20qacnm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('26d4c8c7-a311-4b2a-9a75-445e4a317c83', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Wildcard Record', 'Add wildcard: *.aeroacademy.local IN A 192.168.1.100. Run: dig random.aeroacademy.local +short. What IP resolves?', 100, '$2b$10$JioTme/RiRr4IwxRB1wSO.gzp5QLkw3r6MRKz0p.eIaRY4xqJB5sG'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2bbeba22-ef3e-4b07-a1a6-e1a5720b4470', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Validator', 'Run: named-checkconf /etc/bind/named.conf 2>&1. What is the output (empty means OK)?', 75, '$2b$10$dX1mIxF68M.cHKMB2cg/duJYHe4EMS1PbIAFoO4EnQu0eZMm4dqhK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9a53b26f-eed2-4772-84c8-1776c918dc52', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Dumper', 'Run: dig axfr aeroacademy.local @localhost 2>&1 | wc -l. How many lines in zone transfer?', 100, '$2b$10$zF8UEbLC0CvQ4j75nVuM2.AK23nKYzHfqGQ2ha43ejqGEkbz8kNam'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('aef5fa39-bcd8-4ec7-8b10-5721bdc25f0b', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Cleanup', 'Run: systemctl stop named 2>/dev/null || service named stop 2>/dev/null; echo "dns_done". What is the output?', 75, '$2b$10$3QABAFgXeqy9RRD4ASuKseyf.qdIWh5cM.xjtYqC/ufK8mDOVDayO'ON CONFLICT DO NOTHING)
