INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('08ec90c7-d5a1-429b-833a-0119d1490ec0', '19796c88-1a0a-4c0c-ba7d-4422edecb4fe', 'Cluster Cleanup', 'Run: kubectl delete namespace dev 2>&1 && echo "k8s_cleanup_done". What is the output?', 75, '$2b$10$b2Wxdc18s2Z.DkhGfZqk6uTc1Wdj1aZiAqv7.u1S/6q3vpViN.VQ2'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('64b7ae8f-4ccc-446a-96ec-b92fc5c84a40', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Package Manager', 'Run: yum list installed 2>/dev/null | head -3 || dnf list installed 2>/dev/null | head -3 || echo "package_manager_available". What package manager is available?', 50, '$2b$10$Y/R81owqKK1JB1Owq5O/4O8WTRp6G1Op6u9jvo43KML1lSjvs7iIi'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ed0d4929-24d4-4ec4-a4ac-3bd641518747', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Service Control', 'Run: systemctl list-units --type=service 2>/dev/null | head -3 || service --status-all 2>&1 | head -3 || echo "services_listed". What services are shown?', 50, '$2b$10$pCgr2TReyULqiRbcsfvVqe8L/iXoRulYDuiAxR187YfqI2x5QM.Ga'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('afed86dc-8c24-4031-a676-f2f8f99943fd', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'SELinux Inspector', 'Run: getenforce 2>/dev/null || echo "selinux_not_available". What is the SELinux status?', 75, '$2b$10$Q5vK0efCfyWcKf8kVXOj4OUJhS5tlHCXgNG4KTeFCpBZtHCMG7ZTm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dc59ffad-84c8-4392-a096-7cb466b3418a', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Firewall Manager', 'Run: firewall-cmd --list-all 2>/dev/null || iptables -L -n 2>/dev/null | head -3 || echo "firewall_checked". What firewall is active?', 75, '$2b$10$dGygWrjxx.osSsXjwdTWPOXquKY8dK4dJeDtkM1F.QWPhSklFwaKS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('166d0e11-381c-4b4f-b837-d9f60aa01967', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Yum Repository', 'Create /etc/yum.repos.d/custom.repo with [custom], name=Custom, baseurl=http://example.com/repo, enabled=1. Run: cat /etc/yum.repos.d/custom.repo | grep "name=". What is the repo name?', 100, '$2b$10$d3B7Q1EaLFLI/nYQuPpwd.SZpIrwa5obnYIyAmcAZOKE7cMJkQ6lK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9f6d9f51-07bd-4fe1-bbc7-d2a1f49d96df', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Cron Master', 'Create cron: echo "0 2 * * * /usr/local/bin/backup.sh" | crontab -. Run: crontab -l | head -1. What is the schedule?', 100, '$2b$10$ru7I2xLpCnZhPT9aKb2tyeOjYjBHBQSJDmgJASn25gticFkOdFxaq'ON CONFLICT DO NOTHING)
