INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ef8fd39a-e080-495b-a36e-8161f83550b1', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Journal Inspector', 'Run: journalctl -n 5 2>/dev/null | head -3 || echo "journal_available". Is journalctl available?', 75, '$2b$10$NsnQuRsT2aFQTQ61mNMa7.ET3ysXF0L5H0qlz20LS8oEevjGOwcwO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ad6fa8b8-f02b-4312-b79b-40a6e60a31e2', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'User Manager', 'Create user: useradd -m devuser && id devuser. What UID is assigned?', 100, '$2b$10$5aArnD0fVuYcIdZz4N8kV.VwNj8vzzrl7RLhGoHC8ojQ3bvSMxFem'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fb095c14-4881-4d9b-bfd1-8fafc9dd7485', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Tmpfiles Creator', 'Create /etc/tmpfiles.d/custom.conf with: d /run/custom 0755 root root -. Run: cat /etc/tmpfiles.d/custom.conf | head -1. What path is created?', 100, '$2b$10$9DUnQwS8q.jXzfd9KlM4p.WiHyG0z57oT5sqO3pN2.YbGbl/vGjCK'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a59c17e5-9113-410f-9fa0-ac461bee88b7', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Kernel Module', 'Run: lsmod | head -3 | wc -l. How many kernel modules loaded (minus header)?', 100, '$2b$10$IeRo0CzPlUnyAg7O01LpI.pw7mM4upzcdzvCoQdZ3frbgl41hyuXm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('37f7bdde-972c-4152-ba9c-dacdd9a562ab', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Disk Partitioner', 'Run: lsblk | head -3. What block devices are shown?', 75, '$2b$10$G.YjAYyGNjE4yUBpHQ.h4ue8Wan5I8k9sGlbEjMileNu39vUdsp32'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('34d83a5c-75ba-43c8-a0bd-f3f6b71103fa', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Network Manager', 'Run: ip addr show | grep -c "inet ". How many IPv4 addresses?', 100, '$2b$10$EIhOHr.UcezrnFYG4Y8bduNnGqwrPyfBPeqA1iP1W1OqtWt7jQKOa'ON CONFLICT DO NOTHING)
