INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bedeeb84-6364-46f3-be56-bc98dd402308', 'f6d4f425-9d67-4506-ae35-c713d671e033', 'SSH Hardener', 'Edit /etc/ssh/sshd_config: set PermitRootLogin no. Run: grep "PermitRootLogin" /etc/ssh/sshd_config | tail -1. What is the value?', 75, '$2b$10$NRU4Sr/ZvijJyOlxm9paI.MOKj/CJvbPPE2T3KsYrj9RY49.qrPcq'ON CONFLICT DO NOTHING)
