INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8bcabb5b-4e04-42c9-a0c0-b9c9ddce7f3f', 'f6d4f425-9d67-4506-ae35-c713d671e033', 'Audit Rules', 'Create /etc/audit/rules.d/custom.rules with: -w /etc/passwd -p wa -k passwd_changes. Run: cat /etc/audit/rules.d/custom.rules | grep "passwd". What file is watched?', 100, '$2b$10$FSKpcmFqMt.Cc3Fnb7VFy.ROR1qW4ahGphyFydHv3.NF43EbAnUSm'ON CONFLICT DO NOTHING)
