INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a19364b4-3ed0-4de6-8a8d-9b5f9b2161aa', '8cb79cf7-a12b-4e99-a050-9f067f2b604d', 'Block Devices', 'Run: lsblk -d | head -3. What device names are shown?', 100, '$2b$10$t8udIgqE4xHGkq0Ntpn7cusfgcidaVIZGDZHxvlcZbWrkQuTIotwC'ON CONFLICT DO NOTHING)
