INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c2cc600c-fba1-4689-a85c-9b24c8fd979d', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Process Inspector', 'Run: cat /proc/1/cmdline | tr "\0" " ". What command is PID 1 running?', 50, '$2b$10$cgaHPWzk2g8cLVWPKIInk.0igloOOfilWG72PdQWP6aDAuTgjP1re'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e3070ec9-0d9c-4532-9db7-d4fb370ca525', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'File Creator', 'Create /home/student/container_proof.txt with exact content: I built this container. Run: cat /home/student/container_proof.txt. What is the content?', 50, '$2b$10$AIyKlUWD1atJUemvQ0JNTuy3Yf.yeqH.prAf5uqfXrVNF5xyKJq8.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8ceaa923-cdb8-4f2f-8d50-9a9ed697131b', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Limits Reader', 'Run: cat /proc/1/limits | grep "Max open files" | awk "{print $4}". What is the soft limit for open files?', 75, '$2b$10$BsbXtdi4ZVxvXBMieO17Fe29J78XNome69ESP5XZsuMLHduf.nRTO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5152ad59-fac8-47a5-aefd-38cff9e7e17e', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Script Writer', 'Create /home/student/inspect.sh that outputs exactly CONTAINER_OK. Make executable. Run it. What is the output?', 75, '$2b$10$KlV2eYzjT2N1YioNM2UUGeQurmcywtYuvM3WlH340UJQCdsd0NOou'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('536d4529-ea3b-4bb5-b422-2cb4f6ce70ad', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Permission Setter', 'Create /home/student/locked.txt. Set to chmod 000. Run: stat -c "%a" /home/student/locked.txt. What number?', 75, '$2b$10$U0zFgwIr7jLZhSwZ/KseLeuzcOlJ45989Qa6MkEcoRABxBzkFAH9y'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6496c3b1-9751-4ddf-b435-a0df02cc9e60', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Process Killer', 'Start: sleep 999 &. Kill it: kill $(pgrep sleep | head -1). Run: pgrep sleep | wc -l. How many sleep processes remain?', 75, '$2b$10$LHXj9Vn.Z8UX5mrKryrgP.nEn9hSHtmIVUSrLAOQx98JVHfYQdEoy'ON CONFLICT DO NOTHING)
