INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('82532198-9f4f-461d-87dd-074c34d72168', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Date Formatter', 'Run: date +%Y%m%d. What is today date in YYYYMMDD format?', 75, '$2b$10$P9NEFvBmdCgbA38ub5ctp.rLSxypIrLPGdClNKEXs87D97C/HGjty'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('569c7b33-7403-4032-b613-3bc2af30c695', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'String Length', 'Run: echo -n "AEROACADEMY" | wc -c. How many characters in AEROACADEMY?', 75, '$2b$10$n3KKkQ8nUIL33ypQOX/HO.4407eAIajjPmeWItGWFkMjo4fN/Nub.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3f24cead-f371-4b3c-87e6-5710df26c928', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'File Duplicator', 'Create /home/student/original.txt with "clone me". Copy to /home/student/clone.txt. Run: diff /home/student/original.txt /home/student/clone.txt. What is the output (empty if identical)?', 75, '$2b$10$W.BhE6a7MtCyi5MC.PZS3uJY6VhhgoGfXDZhv62qDWobfgihzwksC'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('25cccb12-c34d-4aaf-b376-7abc8f7e99ec', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Hex Converter', 'Run: echo 255 | xargs printf "%x". What is 255 in hexadecimal?', 100, '$2b$10$b5tZ5iAcu8jznArxG21I1OJVCryMU5ZhQN5BOdsEO/CglFFMAnZ36'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d2238694-ade2-46ff-a172-284d1c2d4481', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Path Resolver', 'Run: realpath /home/student/. What is the absolute path?', 75, '$2b$10$sdz7RO.6HKIiwdtELnJgEu5IxriBN2QwnrtgJ5jwUKhfPrk5bwame'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cfe4f1d2-5c6f-4dda-8947-a6fc388cb816', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Database Creator', 'Create a database called shopdb. Run: mysql -u root -e "SHOW DATABASES" | grep shopdb. What is the output?', 50, '$2b$10$y8IHGz0slzeucAEGQhNvH.ysZqJwHOFCMntpXKM7QTkhmd4fS2FMe'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ffbcbee0-adb2-44ea-9fb6-c368496887f6', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Table Architect', 'Create table products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), price DECIMAL(10,2), stock INT DEFAULT 0). Run: DESCRIBE products | wc -l. How many columns (minus 1 for header)?', 75, '$2b$10$cWLjtGXxqVusUUHTV6lCYuYycBOUp.9CJ01b6ZlyZSLPs/g64XTwu'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('01543ffe-1e92-4499-bed8-7b5d35fd857d', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$IGAe1pqO7iLwWUijWuVPS.TnRJU3OgygFjNVmuPidi8.iQh4k.6xm'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('50bc2901-6caf-412a-8f70-1a7c578bd29c', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product name?', 75, '$2b$10$tLBQ9TJ6DBV7q9.XIZ0kbeSq4y1fO28mw4M7lgwK5o0zg2mzRtj6.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eb1f2699-522c-4877-8c33-31ee4888b0df', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Index Builder', 'Create index on products(name). Run: SHOW INDEX FROM products WHERE Key_name != "PRIMARY" | wc -l. How many non-primary indexes?', 100, '$2b$10$JafzwzIyGfkgxVgrxN8S4uIX3pAq2Vy85RH.TrY3qXKcrh1pk/R26'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('50825553-da22-4db9-9581-d6e7f3f3f307', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'User Manager', 'Create user "appuser"@"localhost" identified by "secret123". Grant SELECT,INSERT on shopdb.*. Run: SHOW GRANTS FOR "appuser"@"localhost" | grep "ON shopdb.*". What privileges are shown?', 100, '$2b$10$blUA4.zClRuPH6.4G9rKLuJ0fvglJPp/fTp3.aVVGPdibJGB36XVu'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('682d76f5-0699-4e8c-98fe-7a9128b6df89', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Backup Creator', 'Run: mysqldump -u root shopdb > /tmp/backup.sql && wc -l /tmp/backup.sql. How many lines in the backup file?', 100, '$2b$10$MYttyVdG1WmaqixHgiSyvOIl1Xr4MCYexpJCjIcXJyn9Mcqx2wcuy'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('05ec841a-e3ba-4565-8e3a-42932f9ce654', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Join Artist', 'Create table orders (id INT PRIMARY KEY AUTO_INCREMENT, product_id INT, quantity INT, FOREIGN KEY (product_id) REFERENCES products(id)). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id | wc -l. How many result rows (minus header)?', 100, '$2b$10$JbAsAYHjNkN9GVoUblqt4uZ1USXRfUnrr.aOk2cE7zupApijstdVO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('aa2dfcd6-b623-4e57-a6ef-f7a85d39d3a4', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total inventory value?', 100, '$2b$10$eFcE3lQFN6T7PCku4.vc2.Ao7y05mqPALNwGLb98Jr6LSb8LxJdL.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5b78984a-93d3-4918-b100-1ad24c12411c', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Transaction Tester', 'Run: mysql -u root shopdb -e "START TRANSACTION; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && mysql -u root shopdb -e "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$4pZ43Tm8AdSDv5K5HuNzNetD3ReljYvjGIYsiZSZsZcWau6yFBB9e'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8383a3e6-c784-4603-b6b1-2f1c2e769a95', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'View Creator', 'Create view cheap_products as SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product appears?', 100, '$2b$10$ftjWwyveAMYauoJIKiQL6OhfrVqp/JdJvOAYkCALaaLAXToYGJv6S'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fd9a93f7-49f3-488d-9b82-cfcef6fba7a1', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Permission Auditor', 'Run: mysql -u root -e "SELECT user FROM mysql.user" | grep appuser. What user is listed?', 75, '$2b$10$9NF5rD5Nt1sE5Q0d.EOjKeSrvGm51x11rGmpumoftI2K7kK3G/yQq'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('db4e3ca6-3dfb-45a6-be8c-db3d969b04ca', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Schema Inspector', 'Run: mysql -u root shopdb -e "SHOW TABLES" | wc -l. How many tables exist (minus header)?', 75, '$2b$10$wdHDlAsoD1XmCttifYjYveBPUBRYRl2IyZzs2mzH8rFCykGtQjQQe'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2f8c68e0-dde6-42b9-b048-19056458d338', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Auto Increment Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$MSZ4e4tCo5.Ovmdj5JfR8.ugMCu6S9Df.KfAFiGE.Kd/mAqFV25Km'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3a8a1f3a-86ce-4052-bd46-2655d8c052be', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name="Mouse" && mysql -u root shopdb -e "SELECT price FROM products WHERE name=''Mouse''". What is the new price (rounded to 2 decimals)?', 100, '$2b$10$9FQ.0QmYzU8/QdEqo922JetN/SjOqHyEQ43J4c/NJs5MJ2Lqoveuu'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6d47ba90-218d-4d8d-bb0e-f7f05a6f4127', '50d6a493-7898-473d-8287-137229593da9', 'Virtual Host Builder', 'Create /etc/nginx/sites-available/mysite.conf with a server block listening on port 9090, root /var/www/mysite. Create /var/www/mysite/index.html with "Hello Custom". Enable the site with ln -s and reload nginx. Run: curl -s localhost:9090. What is the content?', 100, '$2b$10$Clfnbr.S6Bg91qKRKCzpl.xEwasQI8AqZ8rfHREf/7Fjhw9XZkQ7K'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6e4dca37-a0bb-4d81-92ff-45393951c205', '50d6a493-7898-473d-8287-137229593da9', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$eFJX9dcMpjGvtrnkenlV3.7yIPQdB.HGKYNY4vv.xGHI/iAFENnli'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bd9096b8-7a7c-4edd-96e1-d7dbc98b06b6', '50d6a493-7898-473d-8287-137229593da9', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$deouJ.2s1vdTmoi29UvJZeBk.OrjqRcvgDsXARJPrGjqUkT1TCWLS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2163496e-4c9e-4c47-9e5b-c8d4b9af3894', '50d6a493-7898-473d-8287-137229593da9', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$0PJ80JQeq8bFNU8I5hlNEOuzyJFRPr6zEYxfR97dP/2CDQj3AhCdS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c6aae279-31b7-4427-a5e3-16b3a4a40423', '50d6a493-7898-473d-8287-137229593da9', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$OehtuRIsRyFEchQIqGhseeE/1LfFfaZNDjUBEaumYUUgYDaN5TZ4C'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eb24dbaf-4d72-425d-8f59-96356f8ed85f', '50d6a493-7898-473d-8287-137229593da9', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$w4USAzG1rvQFFeBXpYPrs.wiStN7JEXZsFbV52srD3beZNZ4sMJ52'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9fd7d0f7-0004-46a2-bdf4-e0f8a582848a', '50d6a493-7898-473d-8287-137229593da9', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$JQ8D6qpbpIyH0tTujNm6zu1aWAS/Yff/do8Cn.0do7G6GNhhm66m6'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('15d15ed9-b783-4563-9fad-6a80df754010', '50d6a493-7898-473d-8287-137229593da9', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$yDZiWhlrYim7NdDNT9k6V.Ip4o3ZgpYsAJeoRQtGCXQgaU0wwK69.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('279d8ec1-a220-405e-8637-9988c9818937', '50d6a493-7898-473d-8287-137229593da9', 'Log Analyzer', 'Make 5 requests to nginx. Then run: cat /var/log/nginx/access.log | tail -5 | wc -l. How many access log entries?', 75, '$2b$10$SLQDPlwk.PnVbZtFtVU9s.4CdwjWiU/oITu1bAIJUlOPkfn4ZmekW'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a109c9b6-ab65-4f5c-b27d-fecf2093e9f6', '50d6a493-7898-473d-8287-137229593da9', 'Rewrite Master', 'Add to your server config: location /old { return 301 /new; }. Create /var/www/mysite/new.html with "Redirected". Reload. Run: curl -s localhost:9090/old. What is the content after redirect?', 100, '$2b$10$YxvP7tE72cxchtANnUlY3endt2UASMnbstEtH4IYq7Wjrk89gyoru'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('196b9d2b-016e-4b47-a561-8e541d4a8775', '88de7b45-d1c8-4d13-97df-66805199f591', 'Database Creator', 'Create database shopdb using createdb. Run: psql -l | grep shopdb. What is the output?', 50, '$2b$10$MumMRFIGJLCw8Fy/hTX/COtcVerV3j0seQSagVz4fq4WfNTtA0v2i'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5710c2ac-1258-4eac-a41d-204af6886101', '88de7b45-d1c8-4d13-97df-66805199f591', 'Table Architect', 'Create table products (id SERIAL PRIMARY KEY, name VARCHAR(50), price NUMERIC(10,2), stock INT DEFAULT 0). Run: \d products | wc -l. How many lines of column info?', 75, '$2b$10$RO6HE9mYh6SFOIZvr8W05.D1Dz1esxOefmz9XrnXeP7GK07f6Tfby'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f4ce0f91-d03b-4415-8eed-5fdd2fea9e80', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$a3pmdsUe7Gruz7vfihiC/OCI/xG.l7xZLV9zMEZ.Aq7HQ97nSVZNW'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d15d8325-9cbf-45fe-9294-ac2084ad05ac', '88de7b45-d1c8-4d13-97df-66805199f591', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product?', 75, '$2b$10$LUSIlT94cbqf2ZNKQwZaSOhBqnRYRXjp1I2LBQ7Wacf14TF1F/MFa'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3e4f2f87-3b2d-4a55-8bbe-578be7abe488', '88de7b45-d1c8-4d13-97df-66805199f591', 'Index Builder', 'Create index idx_products_name on products(name). Run: \di | grep idx_products_name. What index name is shown?', 100, '$2b$10$b1E4tSHdsMnw/8oQzSD0f.LmnK2bX/dqCUir7Xtpzp8lZ1izIRtYS'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9ebdf5b6-2a99-4f1c-bc6a-46af90c7bcf0', '88de7b45-d1c8-4d13-97df-66805199f591', 'Role Manager', 'Create role appuser LOGIN PASSWORD ''secret123''; Grant CONNECT on shopdb to appuser. Run: \du | grep appuser. What is listed?', 100, '$2b$10$bMrjuMkNPXBwAe/zKd6yuOA23u19J5TSyW0QddG7JDZKKx5OzJd.S'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7e26bc2f-f0e1-4236-9eee-15a57ca5dca1', '88de7b45-d1c8-4d13-97df-66805199f591', 'Backup Creator', 'Run: pg_dump shopdb > /tmp/pgbackup.sql && wc -l /tmp/pgbackup.sql. How many lines?', 100, '$2b$10$4XDEqUL8.kRezOskhjWF/udEqO0WfKH5oIBYAN76It7KxpuNORjmq'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('649d1718-375d-423f-922f-5b74d37fdef3', '88de7b45-d1c8-4d13-97df-66805199f591', 'Join Artist', 'Create table orders (id SERIAL PRIMARY KEY, product_id INT REFERENCES products(id), quantity INT). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id. How many rows (excluding header)?', 100, '$2b$10$key.fYMXPwAe048jxEGSMOmiybOYIRtXLzD5FAdozTcRCIL6199AC'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b3707159-1794-4ef4-a514-650530504578', '88de7b45-d1c8-4d13-97df-66805199f591', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total?', 100, '$2b$10$opBLi/JaQcsFBFsbPcnB6uFTIVjSyxmDppYHWedOVbko73mzU.1Na'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6d847afc-de91-412a-8790-00bb86cc2cd5', '88de7b45-d1c8-4d13-97df-66805199f591', 'Transaction Tester', 'Run: psql shopdb -c "BEGIN; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && psql shopdb -c "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$JodiKXL/gCptbv2oS7F8Geb6AZKPHIMma7ssp8ootzSHrSSstAvgO'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eaf7820f-54bf-4181-b913-cd2fefa85145', '88de7b45-d1c8-4d13-97df-66805199f591', 'View Creator', 'Create view cheap_products AS SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product?', 100, '$2b$10$qrHoMQy0dTIKCCrTaWPBOuTbHRUxTFsFQ4sxG9TmjRbuHYB5FOUJW'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cf999293-5ed0-4d56-9d9b-783892193ea7', '88de7b45-d1c8-4d13-97df-66805199f591', 'Permission Auditor', 'Run: psql -c "SELECT has_table_privilege(''appuser'', ''products'', ''SELECT'')". What is the result?', 75, '$2b$10$DAYkWxWlCFMPP5HT3jXgwOMR59e.l22lFSLsuRHOf4eHJIiy2QyVC'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cd6e5471-9541-44fa-a3dd-4570d1b79cf8', '88de7b45-d1c8-4d13-97df-66805199f591', 'Schema Inspector', 'Run: psql shopdb -c "\dt" | grep -c "product". How many tables match?', 75, '$2b$10$YY58IcQxwfavTBrcWS0mV.iNzDZ8Sx2/MTkaJWvySPzcUeUh8TPy6'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0c687d10-a42f-4759-a820-6025e429b7a8', '88de7b45-d1c8-4d13-97df-66805199f591', 'Serial Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$JK6pj9CP3N/s50.cCdOIkuV./c51qOpmGC6nOkSGL4yquDaT0aRo.'ON CONFLICT DO NOTHING)
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('969e8611-0925-4ef3-b397-fbc667a32588', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name=''Mouse'' and SELECT price FROM products WHERE name=''Mouse''. What is the new price (rounded to 2 decimals)?', 100, '$2b$10$0gJP2dkoRHqFOgPtzI8bd.J8ghRLhkCUceeJ6ywqEqryyqOekGemK'ON CONFLICT DO NOTHING)
